  @case 'a deleted step takes the root\'s index down with it'  [pure]  @ 294-304
  @case 'deleting the rooted step restates the root on the unison'  [pure]  @ 308-325
  @case 'a step sorted below the root carries the root\'s index'  [pure]  @ 329-338
  @case 'retuning the rooted step moves the scale, not the root'  [pure]  @ 342-355
  @case 'a temper stating no root comes through both edits unstamped'  [pure]  @ 359-370
  @case 'midiName spells a pitch in the untempered twelve names'  [pure]  @ 374-380
  @case 'the default root reduces the conversions to MIDI-relative arithmetic'  [pure]  @ 384-399
  @case 'stepWindow halves the distance to each neighbour, wrapping at both ends'  [pure]  @ 403-416
  @case 'stepWindow under an unequal scale reports two different halves'  [pure]  @ 420-432
  @case 'a flattened root moves every pitch by its offset and renames nothing'  [pure]  @ 436-458
  @case 'an octave-shifted root renames every octave and moves no pitch'  [pure]  @ 462-478
  @case 'the conversions invert each other at every root'  [pure]  @ 482-495
  @case 'EDO presets carry n\\m source tokens that derive back to their cents'  [pure]  @ 499-506
  @case 'parseScalaFile strips comments, description and count; returns pitch tokens'  [pure]  @ 510-518
  @case 'parseScalaPitches keeps every non-comment, non-blank line'  [pure]  @ 522-527
  @case 'scalaToTemper prepends the unison, splits the period, flags periodAsStep'  [pure]  @ 531-542
  @case 'scalaToTemper sorts unordered pitches ascending; widest becomes the period'  [pure]  @ 546-555
  @case 'scalaToTemper rejects an unparseable token'  [pure]  @ 559-564
  @case 'genEqual: full EDO and a diatonic subset, base implicit, period last'  [pure]  @ 568-580
  @case 'edoDegrees: relative cumulates, absolute sorts; non-octave equave suffixes'  [pure]  @ 584-592
  @case 'degreesToSpec round-trips edoDegrees in both modes'  [pure]  @ 596-600
  @case 'genHarmonics / genSubharmonics: rooted on the low harmonic, top is period'  [pure]  @ 604-613
  @case 'genChord: otonal vs inverted, last member is the period'  [pure]  @ 617-629
  @case 'parseChord rejects fewer than two notes or non-integers'  [pure]  @ 633-637
  @case 'genCPS: hexany rooted on the smallest product, 1/1 first, ascending'  [pure]  @ 641-647
